<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\ActivityLog;use App\Models\Customer;use App\Models\Lead;use App\Models\PricingRule;use App\Models\WebsiteSetting;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class UtilityController extends Controller { public function collection(Request $r,string $type){$data=match($type){'customers'=>Customer::latest()->paginate(100),'leads'=>Lead::latest()->paginate(100),'pricing'=>PricingRule::latest()->paginate(100),'activity'=>ActivityLog::with('user')->latest()->paginate(100),'notifications'=>DB::table('notifications')->latest()->paginate(100),'reports'=>['bookings_total'=>DB::table('bookings')->count(),'completed_revenue'=>(float)DB::table('bookings')->where('status','Completed')->sum('total_price')],'users'=>DB::table('users')->select('id','name','email','role','is_active','created_at')->latest()->paginate(100),'media'=>DB::table('media')->latest()->paginate(100),'seo'=>DB::table('seo_metadata')->latest()->paginate(100),default=>[]};return response()->json(is_array($data)?['data'=>$data]:$data);} }
